 if 'platform_message_id' not in cols:continue
 rows=db.execute('SELECT id,session_id,role,platform_message_id FROM messages WHERE platform_message_id IN (?,?,?,?,?)',('1791583414.049519','1791586035.851579','1791619946.729429','1791620176.499449','1791620315.128649')).fetchall()
 if rows:
  print('matching_db',str(p)); print('message_links',json.dumps([dict(r) for r in rows]));print('session_columns',[r[1] for r in db.execute('PRAGMA table_info(sessions)')])
  for sid in {r['session_id'] for r in rows}:
   row=dict(db.execute('SELECT * FROM sessions WHERE id=?',(sid,)).fetchone()); print('session_metadata',json.dumps({k:v for k,v in row.items() if k in ('id','source','model','started_at','ended_at','metadata','title','parent_session_id')}))
 db.close()
for p in (home/'.clanker-cloud/kernel/contexts').glob('*.json'):
 d=json.loads(p.read_text())
 if d.get('owner')!={'team':'T0C6J1XCDE0','requester':'U0C688SF7DZ'}:continue
