 if not matches:continue
 print('owned_context',str(p),json.dumps({'owner':d['owner'],'threads':matches}))
 for name in set(matches.values()):
  e=d['sessions'].get(name,{})
  print('kernel_entry',json.dumps({'name':name,**{k:v for k,v in e.items() if k in ('session_id','session_name','home','created_at','updated_at','last_used_at','started_at')}}))
